import { GENRES, EXPERIENCE_SEED, COPY_PACK_SECTIONS, INITIAL_PROJECT } from './data.js';
import { STORAGE_KEY, SETTINGS_KEY, REPO_CATEGORY_LABELS, reviewExperience, recommendGenres, buildGenreAdvice, projectCompleteness, progressFor, localQa, strictScore, scoreLabel, evidenceProfile, escapeHtml, uid, canonicalWorkKey, inferRepoCatalogEntry, mergeRepoCatalog } from './core.js';

const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)], clone=x=>JSON.parse(JSON.stringify(x));
const defaults=window.NARRATIVE_AGENT_DEFAULTS||{};
let state=loadState(),settings=loadSettings(),currentView='dashboard',currentProjectId=state.projects[0]?.id||null,currentProjectTab='bible',portfolioQuery='',portfolioCategory='all';

function normalizeProject(p){p.chat=Array.isArray(p.chat)?p.chat:[];p.copySections=Array.isArray(p.copySections)?p.copySections:[];p.copyPlan=p.copyPlan||null;p.review=p.review||null;p.portfolioAudit=p.portfolioAudit||null;p.githubReview=p.githubReview||null;return p;}
function normalizePortfolioScan(scan){if(!scan||typeof scan!=='object')return null;scan.owner=String(scan.owner||'');scan.repoNames=Array.isArray(scan.repoNames)?scan.repoNames:[];scan.batches=Array.isArray(scan.batches)?scan.batches:[];scan.pending=Array.isArray(scan.pending)?scan.pending:[];scan.errors=Array.isArray(scan.errors)?scan.errors:[];scan.phase=scan.phase||'idle';scan.startedAt=Number(scan.startedAt||Date.now());scan.updatedAt=Number(scan.updatedAt||scan.startedAt);scan.finished=!!scan.finished;scan.message=scan.message||'';return scan;}
function loadState(){let v=null;try{v=JSON.parse(localStorage.getItem(STORAGE_KEY));}catch{}if(!v){try{v=JSON.parse(localStorage.getItem('narrative_agent_state_v1'));}catch{}}if(v&&Array.isArray(v.projects)&&Array.isArray(v.experiences)){v.projects.forEach(normalizeProject);const known=new Set(v.experiences.map(x=>x.id));for(const seed of EXPERIENCE_SEED)if(!known.has(seed.id))v.experiences.push(clone(seed));v.portfolioAudit=v.portfolioAudit||null;v.portfolioScan=normalizePortfolioScan(v.portfolioScan);v.repoCache=Array.isArray(v.repoCache)?v.repoCache:[];v.repoCatalog=Array.isArray(v.repoCatalog)?v.repoCatalog:mergeRepoCatalog(v.repoCache,[]);v.version=4;return v;}return{projects:[normalizeProject(clone(INITIAL_PROJECT))],experiences:clone(EXPERIENCE_SEED),portfolioAudit:null,portfolioScan:null,repoCache:[],repoCatalog:[],version:4};}
function loadSettings(){let v={};try{v=JSON.parse(localStorage.getItem(SETTINGS_KEY))||{};}catch{}return{workerUrl:v.workerUrl??defaults.workerUrl??'',appKey:v.appKey??'',githubOwner:v.githubOwner??defaults.githubOwner??'Mike798-cloud'};}
function serializableState(){const c=clone(state);for(const p of c.projects||[])delete p.lastImage;return c;}
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(serializableState()));return true;}catch(e){console.warn(e);return false;}}
function saveSettings(){localStorage.setItem(SETTINGS_KEY,JSON.stringify(settings));}
function activeProject(){return state.projects.find(p=>p.id===currentProjectId)||state.projects[0]||null;}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>t.classList.remove('show'),2800);}
function setBusy(v){document.body.classList.toggle('loading',v);}
function navMeta(){return{dashboard:['WORKSHOP / OVERVIEW','制作总览'],projects:['WORKSHOP / PROJECTS','项目工作台'],genre:['METHOD / GENRE DNA','类型判断'],experience:['KNOWLEDGE / EXPERIENCE','经验库'],portfolio:['ARCHIVE / PORTFOLIO','作品集复盘'],studio:['AGENT / PRODUCTION','AI 制作台'],qa:['REVIEW / QA','独立 QA'],settings:['SYSTEM / SETTINGS','连接与部署']}[currentView];}
function render(){const meta=navMeta();$('#viewEyebrow').textContent=meta[0];$('#viewTitle').textContent=meta[1];$$('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView));$('#content').innerHTML=({dashboard:renderDashboard,projects:renderProjects,genre:renderGenre,experience:renderExperience,portfolio:renderPortfolio,studio:renderStudio,qa:renderQa,settings:renderSettings}[currentView])();bindView();hydrateVisibleImage();}
function genreTags(p){return(p.genres||[]).map(g=>`<span class="tag ${g.score>=60?'hot':''}">${escapeHtml(GENRES.find(x=>x.id===g.id)?.name||g.id)} ${g.score||''}</span>`).join('');}
function issueHtml(i){return`<div class="issue"><div class="sev ${i.severity}">${i.severity}</div><div><strong>${escapeHtml(i.title)}</strong><p>${escapeHtml(i.detail)}</p></div></div>`;}
function progressRow(p,name,field){const pct=progressFor(p,field);return`<div style="margin:10px 0"><div style="display:flex;justify-content:space-between;font-size:11px"><span>${name}</span><span class="mono">${pct}%</span></div><div class="progress"><span style="width:${pct}%"></span></div></div>`;}
function reviewBadge(p){const s=strictScore(p),e=evidenceProfile(p);return s===null?`<span class="tag bad">${e.reviewStale?'评分已过期':'证据制评分：未运行'}</span>`:`<span class="tag ok">独立评分 ${s.toFixed(2)}/10</span>`;}

function renderDashboard(){const p=activeProject(),issues=p?localQa(p):[],coverage=p?projectCompleteness(p):0,s=p?strictScore(p):null;return`<section class="hero"><div><div class="eyebrow">CREATIVE DIRECTOR SYSTEM</div><h3>从一个念头，走到可验证、可发布的网页叙事游戏。</h3><p>Agent 把故事事实层、玩家认知层、页面依赖、谜题、文案、视觉、作品经验与发布 QA 放在同一条流水线上。数字不再奖励“填满字段”，真正 10 分制必须由独立评审给出证据。</p></div><div class="hero-note"><strong>${p?escapeHtml(p.title):'还没有项目'}</strong><span>${p?`验收准备度 ${coverage}% · ${s===null?'尚未独立评分':`独立评分 ${s.toFixed(2)}/10`}`:'先新建项目。'}</span></div></section><div class="metrics"><div class="metric"><div class="num">${state.projects.length}</div><div class="label">项目</div><div class="delta">LOCAL-FIRST</div></div><div class="metric"><div class="num">${state.experiences.length}</div><div class="label">方法论经验</div><div class="delta">先去重再保存</div></div><div class="metric"><div class="num">${state.portfolioAudit?.repoCount||0}</div><div class="label">已复盘公开仓库</div><div class="delta">实际引用链</div></div><div class="metric"><div class="num">${s===null?'—':s.toFixed(2)}</div><div class="label">独立质量评分</div><div class="delta">${s===null?'证据不足不硬算':'只看最终产物'}</div></div></div><section class="section"><div class="section-head"><div><h3>当前项目</h3><p class="lead">验收准备度只表示材料是否足够进入评审，不等于作品质量。</p></div><button class="btn small" data-go="projects">进入工作台</button></div>${p?projectSummary(p):'<div class="empty">没有项目。</div>'}</section><section class="section"><div class="section-head"><div><h3>优先处理</h3><p class="lead">先处理阻断项，再谈 9.5。</p></div><button class="btn small" data-go="qa">完整 QA</button></div>${issues.length?issues.slice(0,6).map(issueHtml).join(''):'<div class="empty">未发现规则级硬伤。</div>'}</section>`;}
function projectSummary(p){return`<div class="grid-2"><div class="panel emphasis"><h4>${escapeHtml(p.title)}</h4><p>${escapeHtml(p.concept)}</p><div>${genreTags(p)} ${reviewBadge(p)}</div></div><div class="panel"><h4>验收准备度</h4>${progressRow(p,'故事圣经','bible')}${progressRow(p,'页面架构','architecture')}${progressRow(p,'谜题','puzzles')}${progressRow(p,'完整文案','copyPack')}${progressRow(p,'视觉','visual')}${progressRow(p,'QA','qa')}</div></div>`;}

function renderProjects(){const p=activeProject();return`<section class="section"><div class="section-head"><div><h3>项目库</h3><p class="lead">项目状态保存在浏览器；生成图片另存 IndexedDB，刷新不会消失。</p></div><button class="btn primary small" id="createProjectInline">新建项目</button></div><div class="project-list">${state.projects.map(x=>`<div class="project-row"><div><div class="project-title">${escapeHtml(x.title)}</div><div class="tiny muted">${escapeHtml(x.concept).slice(0,80)}</div></div><div>${genreTags(x)}</div><div><span class="mono tiny">准备度 ${projectCompleteness(x)}%</span><div class="progress"><span style="width:${projectCompleteness(x)}%"></span></div></div><div><button class="btn small" data-open-project="${x.id}">打开</button></div></div>`).join('')}</div></section>${p?renderProjectWorkspace(p):''}`;}
function renderProjectWorkspace(p){const tabs=[['bible','故事圣经'],['architecture','页面架构'],['puzzles','谜题图'],['copyPack','完整文案'],['visual','视觉方向'],['imagePrompt','图片设计'],['deploy','发布说明']];const labels={bible:'事实层、人物、知识边界、真实时间线、玩家认知层与最终真相。',architecture:'每个站点/页面的存在理由、进入原因、可见信息、主要出口与跨页关系。',puzzles:'谜题依赖、答案来源、误导、提示层、失败反馈与回报。',copyPack:'长篇文案建议先生成文案矩阵，再逐单元落地并做一致性检查。',visual:'不同载体的年代、机构、材质、排版、美术边界与演出策略。',imagePrompt:'先定义图片世界内来源，再生成镜头、构图与缺陷要求。',deploy:'GitHub Pages / Cloudflare Worker 的发布检查、实际引用文件、移动端和回归测试。'};const taskMap={bible:'story_bible',architecture:'page_architecture',puzzles:'puzzle_design',copyPack:'copy_pack',visual:'visual_direction',imagePrompt:'image_direction',deploy:'release_plan'};const copyTools=currentProjectTab==='copyPack'?`<div class="copy-tools"><button class="btn" id="copyPlanBtn">生成文案矩阵</button>${p.copySections?.length?'<button class="btn" id="copyAllBtn">逐段补齐未完成文案</button>':''}<span class="tiny muted">${p.copySections?.length?`${p.copySections.filter(x=>x.text).length}/${p.copySections.length} 单元已完成`:'尚未建立分段矩阵'}</span></div>${renderCopySections(p)}`:'';return`<section class="section"><div class="section-head"><div><div class="eyebrow">ACTIVE PROJECT</div><h3>${escapeHtml(p.title)}</h3><p class="lead">${escapeHtml(p.concept)}</p></div><div class="split-actions"><button class="btn small" id="editProjectMeta">编辑立项</button><button class="btn small danger" id="deleteProject">删除项目</button></div></div><div class="tabs">${tabs.map(([id,n])=>`<button data-project-tab="${id}" class="${currentProjectTab===id?'active':''}">${n}</button>`).join('')}</div><div class="workspace"><div class="editor field"><label>${labels[currentProjectTab]}</label><textarea id="projectEditor" data-field="${currentProjectTab}" placeholder="可手写，也可以让 AI 生成后继续修改。">${escapeHtml(p[currentProjectTab]||'')}</textarea><div class="split-actions"><button class="btn primary" data-ai-task="${taskMap[currentProjectTab]}">AI 生成 / 深化</button><button class="btn" id="saveProjectField">保存当前内容</button>${currentProjectTab==='imagePrompt'?'<button class="btn" id="generateImageBtn">生成图片</button>':''}</div><div id="imageArea"></div>${copyTools}</div><aside class="side-rail"><div class="rail-block"><h5>类型 DNA</h5>${genreTags(p)}</div><div class="rail-block"><h5>验收准备度</h5><div class="score-ring"><strong>${projectCompleteness(p)}</strong><small>EVIDENCE</small></div><p>不是作品评分。</p></div><div class="rail-block"><h5>独立评分</h5>${reviewBadge(p)}<p>${p.review?.summary?escapeHtml(p.review.summary):'需在 QA 页运行证据制评审。'}</p></div><div class="rail-block"><h5>快速风险</h5>${localQa(p).slice(0,4).map(issueHtml).join('')||'<p>未发现明显结构缺口。</p>'}</div></aside></div></section>`;}
function renderCopySections(p){if(!p.copySections?.length)return'';return`<div class="copy-section-list">${p.copySections.map((s,i)=>`<article class="copy-section"><div><span class="scope">${String(i+1).padStart(2,'0')} / ${escapeHtml(s.surface||'文案')}</span><h4>${escapeHtml(s.title||s.id)}</h4><p>${escapeHtml(s.reveal||'')}</p><small>${s.text?`已生成 ${s.text.length} 字`:`目标约 ${s.targetWords||'—'} 字`}</small></div><button class="btn small ${s.text?'':'primary'}" data-copy-section="${escapeHtml(s.id)}">${s.text?'重写':'生成'}</button></article>`).join('')}</div>`;}

function renderGenre(){const p=activeProject(),concept=p?.concept||'',advice=buildGenreAdvice(recommendGenres(concept));return`<section class="hero"><div><div class="eyebrow">GENRE IS A METHOD, NOT A SKIN</div><h3>类型决定证据和体验，不只是页面颜色。</h3><p>本格、变格、伪网站、密室、社交、档案与 T+P 会改变线索公平性、信息释放、页面结构和交互方式。</p></div><div class="hero-note"><strong>AI 判断可直接写回 DNA</strong><span>不会再只显示一段无法应用的建议。</span></div></section><section class="section"><div class="grid-2"><div class="panel"><h4>项目构想</h4><div class="field"><textarea id="genreConcept">${escapeHtml(concept)}</textarea></div><div class="split-actions"><button class="btn primary" id="genreLocalBtn">本地快速判断</button><button class="btn" id="genreAiBtn">AI 深度判断并应用</button></div></div><div class="panel"><h4>当前建议</h4><div id="genreResults" class="genre-results">${advice.map(genreAdviceHtml).join('')}</div></div></div></section><section class="section"><div class="grid-2">${GENRES.map(g=>`<div class="panel"><h4>${escapeHtml(g.name)}</h4><p><b>核心：</b>${escapeHtml(g.core)}</p><p><b>页面：</b>${escapeHtml(g.style)}</p>${g.avoid.map(x=>`<span class="tag bad">避免 ${escapeHtml(x)}</span>`).join('')}</div>`).join('')}</div></section>`;}
function genreAdviceHtml(g){return`<div class="genre-row"><div class="genre-score">${g.score}<small>%</small></div><div><h4>${escapeHtml(g.name)}</h4><p>${escapeHtml(g.core)}</p><p><b>风格：</b>${escapeHtml(g.style)}</p></div><div>${g.avoid.slice(0,2).map(x=>`<span class="tag bad">${escapeHtml(x)}</span>`).join('')}</div></div>`;}

function renderExperience(){const cats=['全部',...new Set(state.experiences.map(x=>x.category))];return`<section class="hero"><div><div class="eyebrow">LIVING METHOD LIBRARY</div><h3>经验可以增长，但先判断是否重复、是否值得长期保存。</h3><p>AI 深审会返回“合并 / 保存 / 临时 / 拒绝”以及作用范围；不再把所有建议硬编码成项目经验。</p></div><div class="hero-note"><strong>${state.experiences.length} 条经验</strong><span>${state.portfolioAudit?'作品集复盘总结也会作为所有项目的上下文。':'建议先完成一次 GitHub 作品集复盘。'}</span></div></section><section class="section"><div class="grid-2"><div class="panel emphasis"><h4>补充经验</h4><div class="field"><textarea id="experienceInput" placeholder="例如：论坛里的生活帖不能全部为了线索服务，不然一眼就像作者布置的谜题。"></textarea></div><div class="split-actions"><button class="btn primary" id="reviewExperienceBtn">本地评审</button><button class="btn" id="reviewExperienceAiBtn">AI 深审</button></div></div><div class="panel"><h4>评审结果</h4><div id="experienceReview" class="muted tiny">还没有待评审内容。</div></div></div></section><section class="section"><div class="section-head"><div><h3>经验库</h3></div><select id="experienceFilter">${cats.map(c=>`<option>${c}</option>`).join('')}</select></div><div class="experience-list" id="experienceList">${experienceListHtml(state.experiences)}</div></section>`;}
function experienceListHtml(list){return list.map(x=>`<div class="experience-item"><div><span class="scope">${escapeHtml(x.scope)} / ${escapeHtml(x.category)}</span><div class="priority">P${6-(x.priority||3)}</div></div><div><h4>${escapeHtml(x.title)}</h4><p>${escapeHtml(x.body)}</p><div>${(x.genres||[]).map(id=>`<span class="tag">${escapeHtml(GENRES.find(g=>g.id===id)?.name||id)}</span>`).join('')}</div></div><button class="btn small danger" data-delete-exp="${x.id}">删除</button></div>`).join('');}

function portfolioProcessed(scan){const set=new Set();for(const b of scan?.batches||[])for(const n of b.repos||[])set.add(n);for(const x of scan?.pending||[])if(x?.name)set.add(x.name);return set;}
function ensureRepoCatalog(){state.repoCatalog=mergeRepoCatalog(state.repoCache||[],state.repoCatalog||[]);return state.repoCatalog;}
function catalogEntry(repoName){return(state.repoCatalog||[]).find(x=>x.repo===repoName)||null;}
function updateCatalogFromScan(repoName,scan){const repo=(state.repoCache||[]).find(x=>x.name===repoName)||{name:repoName};const old=catalogEntry(repoName);const next=inferRepoCatalogEntry(repo,scan,old);state.repoCatalog=(state.repoCatalog||[]).filter(x=>x.repo!==repoName);state.repoCatalog.push(next);state.repoCatalog.sort((a,b)=>String(b.updated_at||'').localeCompare(String(a.updated_at||'')));}
function repoCategoryOptions(selected){return Object.entries(REPO_CATEGORY_LABELS).map(([id,label])=>`<option value="${id}" ${id===selected?'selected':''}>${escapeHtml(label)}</option>`).join('');}
function catalogCounts(){const c=ensureRepoCatalog(),out={all:c.length,game:0,guide:0,old:0,test:0,tool:0,unknown:0};for(const x of c)out[x.category]=(out[x.category]||0)+1;return out;}
function workGroups(){const groups=new Map();for(const x of ensureRepoCatalog()){if(x.category==='tool')continue;const key=x.workKey||canonicalWorkKey(x.repo)||x.repo.toLowerCase();if(!groups.has(key))groups.set(key,{key,repos:[]});groups.get(key).repos.push(x);}const rank={game:0,unknown:1,guide:2,old:3,test:4};return[...groups.values()].map(g=>{g.repos.sort((a,b)=>(rank[a.category]??9)-(rank[b.category]??9)||String(b.updated_at||'').localeCompare(String(a.updated_at||'')));g.main=g.repos.find(x=>x.category==='game')||g.repos.find(x=>x.category==='unknown')||g.repos[0];g.guides=g.repos.filter(x=>x.category==='guide');g.old=g.repos.filter(x=>x.category==='old');g.tests=g.repos.filter(x=>x.category==='test');g.title=g.main?.signals?.titles?.[0]||g.main?.workTitle||g.main?.repo||g.key;g.linkedProject=state.projects.find(p=>p.githubWorkKey===g.key)||null;return g;}).sort((a,b)=>String(b.main?.updated_at||'').localeCompare(String(a.main?.updated_at||'')));}
function portfolioProgressHtml(){ensureRepoCatalog();const repos=(state.repoCache||[]).filter(r=>!r.archived&&!r.fork&&catalogEntry(r.name)?.category!=='tool'),scan=state.portfolioScan;if(!scan)return`<p>${repos.length?`已读取 ${repos.length} 个公开原创仓库。点击“开始全量扫描”后会自动分批检查。`:'尚未读取仓库列表。'}</p>`;const done=portfolioProcessed(scan).size,total=scan.repoNames?.length||repos.length,repoSet=new Set(scan.repoNames||[]),failed=new Set((scan.errors||[]).filter(x=>repoSet.has(x.repo)).map(x=>x.repo)).size,pct=total?Math.min(100,Math.round(done/total*100)):0;const phase={inspect:'正在检查实际引用链',review:'正在让 AI 总结当前批次',synthesis:'正在合并全作品方法论',done:'扫描完成',paused:'扫描已暂停',error:'扫描异常，可继续'}[scan.phase]||'等待继续';return`<div class="scan-status"><div><b>${done}/${total}</b> · ${escapeHtml(phase)}</div><div class="tiny muted">${escapeHtml(scan.message||'')} ${failed?`· ${failed} 个仓库曾失败/超时`:''}</div><div class="progress"><span style="width:${pct}%"></span></div>${scan.updatedAt?`<div class="tiny muted">断点已保存 · ${new Date(scan.updatedAt).toLocaleTimeString()}</div>`:''}</div>`;}
function workGroupHtml(g){const main=g.main,repoNames=g.repos.map(x=>x.repo).join('、'),homepage=main?.homepage||(main?.has_pages?`https://${settings.githubOwner.toLowerCase()}.github.io/${main.repo}/`:''),linked=g.linkedProject,hasGame=g.repos.some(x=>x.category==='game');const uncertain=g.repos.some(x=>x.category==='unknown')||!hasGame;return`<article class="work-card ${uncertain?'uncertain':''}"><div class="work-card-head"><div><span class="scope">${escapeHtml(g.key)}</span><h4>${escapeHtml(g.title)}</h4></div><div>${linked?'<span class="tag ok">已建立项目</span>':''}${!hasGame?'<span class="tag bad">未确认主游戏</span>':g.repos.some(x=>x.category==='unknown')?'<span class="tag bad">含待确认仓库</span>':''}</div></div><p class="tiny muted">${escapeHtml(main?.description||'没有仓库描述')}</p><div class="work-repos"><span class="tag hot">${hasGame?'主':'候选'} ${escapeHtml(main?.repo||'—')}</span>${g.guides.map(x=>`<span class="tag">攻略 ${escapeHtml(x.repo)}</span>`).join('')}${g.old.map(x=>`<span class="tag">旧版 ${escapeHtml(x.repo)}</span>`).join('')}${g.tests.map(x=>`<span class="tag">测试 ${escapeHtml(x.repo)}</span>`).join('')}</div><div class="work-meta"><span>仓库 ${g.repos.length}</span><span>${main?.signals?`可达文件 ${main.signals.referencedFiles||0}`:'尚未深扫'}</span><span>${main?.updated_at?`更新 ${String(main.updated_at).slice(0,10)}`:''}</span></div><div class="split-actions"><button class="btn small ${linked?'':'primary'}" data-work-project="${escapeHtml(g.key)}">${linked?'打开项目':'建立项目工作区'}</button><button class="btn small" data-work-analyze="${escapeHtml(g.key)}">深度复盘主仓</button>${main?.repoUrl?`<a class="btn small link-btn" target="_blank" rel="noopener" href="${escapeHtml(main.repoUrl)}">GitHub</a>`:''}${homepage?`<a class="btn small link-btn" target="_blank" rel="noopener" href="${escapeHtml(homepage)}">部署站点</a>`:''}</div><details><summary class="tiny muted">查看关联仓库：${escapeHtml(repoNames)}</summary></details></article>`;}
function repoCatalogTableHtml(){let list=ensureRepoCatalog();const q=portfolioQuery.trim().toLowerCase();if(q)list=list.filter(x=>`${x.repo} ${x.description||''} ${x.workKey||''}`.toLowerCase().includes(q));if(portfolioCategory!=='all')list=list.filter(x=>x.category===portfolioCategory);return list.length?`<div class="repo-organizer">${list.map(x=>`<div class="repo-organizer-row"><div><b class="mono">${escapeHtml(x.repo)}</b><p>${escapeHtml(x.description||'')}</p><small>${escapeHtml(x.reason||'')} · ${Math.round(Number(x.confidence||0)*100)}% ${x.manual?'· 人工锁定':x.source==='ai'?'· AI校正':'· 本地初判'}</small></div><select data-repo-category="${escapeHtml(x.repo)}">${repoCategoryOptions(x.category)}</select><div class="field compact-field"><label>作品归组</label><input data-repo-workkey="${escapeHtml(x.repo)}" value="${escapeHtml(x.workKey||'')}" title="相同归组值会被整理为同一部作品"></div><div class="split-actions">${x.manual?`<button class="btn small" data-repo-auto="${escapeHtml(x.repo)}">恢复自动</button>`:''}${x.signals?'<span class="tag ok">已深扫</span>':'<span class="tag">未深扫</span>'}</div></div>`).join('')}</div>`:'<div class="empty">当前筛选没有仓库。</div>';}
function renderPortfolio(){ensureRepoCatalog();const a=state.portfolioAudit,repos=state.repoCache||[],scan=state.portfolioScan,done=scan?.finished,counts=catalogCounts(),groups=workGroups(),visibleGroups=groups.filter(g=>{if(!portfolioQuery.trim())return true;const q=portfolioQuery.toLowerCase();return`${g.title} ${g.key} ${g.repos.map(x=>x.repo).join(' ')}`.toLowerCase().includes(q);});return`<section class="hero"><div><div class="eyebrow">PORTFOLIO EVIDENCE</div><h3>先把几十个仓库整理成“作品”，再从历史项目里提炼方法。</h3><p>一个仓库不一定等于一部作品：主游戏、攻略、旧版和测试仓库会自动归组；分类只是建议，任何 AI 判断都允许人工纠正并锁定。</p></div><div class="hero-note"><strong>${groups.length} 个作品归组 · ${repos.length} 个仓库</strong><span>${counts.unknown?`${counts.unknown} 个仓库仍待确认`:'仓库分类已无待确认项'}${a?.completedAt?` · 全量复盘 ${new Date(a.completedAt).toLocaleDateString()}`:''}</span></div></section><div class="metrics portfolio-metrics"><div class="metric"><div class="num">${counts.game}</div><div class="label">主游戏候选</div><div class="delta">GAME</div></div><div class="metric"><div class="num">${counts.guide}</div><div class="label">攻略仓库</div><div class="delta">GUIDE</div></div><div class="metric"><div class="num">${counts.old+counts.test}</div><div class="label">旧版 / 测试</div><div class="delta">ARCHIVE</div></div><div class="metric"><div class="num">${counts.unknown}</div><div class="label">待人工确认</div><div class="delta">REVIEW</div></div></div><section class="section"><div class="section-head"><div><h3>仓库扫描</h3><p class="lead">默认排除 fork、archived 与明显工具/服务仓；攻略、旧版、测试会作为所属作品的辅助材料而非独立作品。每批 6 个仓库、最多 3 个并发检查。</p></div><div class="split-actions"><button class="btn" id="loadReposBtn">刷新仓库列表</button><button class="btn primary" id="scanPortfolioBtn">${scan&&!done?'继续扫描':done?'重新扫描全部':'开始全量扫描'}</button>${scan&&!done?'<button class="btn" id="pausePortfolioBtn">本批结束后暂停</button>':''}${scan?'<button class="btn danger" id="resetPortfolioScanBtn">清除断点</button>':''}</div></div><div id="portfolioProgress" class="panel">${portfolioProgressHtml()}</div>${scan?.errors?.length?`<details class="scan-errors"><summary>失败/超时记录 ${scan.errors.length}</summary><div>${scan.errors.slice(-20).map(x=>`<p><b>${escapeHtml(x.repo||'未知仓库')}</b> · ${escapeHtml(x.error||'')}</p>`).join('')}</div></details>`:''}</section><section class="section"><div class="section-head"><div><h3>作品整理</h3><p class="lead">先用本地规则初判，再可让 AI 批量校正；人工修改后会锁定，后续同步不会覆盖你的判断。</p></div><div class="split-actions"><button class="btn" id="aiCatalogBtn">AI 校正分类</button><button class="btn" id="resetCatalogAutoBtn">重算未锁定项</button></div></div><div class="organizer-controls"><input id="portfolioSearch" value="${escapeHtml(portfolioQuery)}" placeholder="搜索作品或仓库"><select id="portfolioCategory"><option value="all">全部分类</option>${Object.entries(REPO_CATEGORY_LABELS).map(([id,label])=>`<option value="${id}" ${portfolioCategory===id?'selected':''}>${escapeHtml(label)}</option>`).join('')}</select><span id="catalogStatus" class="tiny muted">${counts.unknown?`还有 ${counts.unknown} 个待确认仓库`:'分类已整理'}</span></div><div class="work-grid">${visibleGroups.slice(0,60).map(workGroupHtml).join('')||'<div class="empty">先刷新仓库列表。</div>'}</div><details class="repo-details"><summary>逐仓校正分类与归组（${counts.all}）</summary>${repoCatalogTableHtml()}</details></section><section class="section"><div class="section-head"><div><h3>作品集方法论总结</h3><p class="lead">这份总结作为剧情、页面、文案、QA 的共同上下文；扫描失败或降级批次会降低结论置信度。</p></div></div><div class="panel audit-output">${a?.summary?escapeHtml(a.summary):'尚未生成。'}</div></section>`;}

function renderStudio(){const p=activeProject();const chat=p?.chat||[];return`<section class="section"><div class="section-head"><div><h3>AI 制作台</h3><p class="lead">聊天记录按项目隔离，不会再在不同作品之间串线。</p></div></div>${!p?'<div class="empty">先创建项目。</div>':`<div class="grid-3"><button class="panel" data-studio-task="project_blueprint"><h4>完整项目策划</h4><p>从定位到发布的制作蓝图。</p></button><button class="panel" id="studioCopyPlan"><h4>文案生产矩阵</h4><p>先拆文案单元，再逐段生成，避免 9000 token 一次硬塞整部作品。</p></button><button class="panel" data-studio-task="virtual_player"><h4>虚拟玩家测试</h4><p>只基于当前可见信息判断卡点。</p></button><button class="panel" id="studioStrictReview"><h4>证据制严格评分</h4><p>材料不足就不评分；评分必须带分项证据。</p></button><button class="panel" data-studio-task="anti_ai_review"><h4>AI 味审查</h4><p>文本、UI、美术与人物声线专项检查。</p></button><button class="panel" id="githubAnalyzeCard"><h4>单仓实际引用复盘</h4><p>从入口追踪真实依赖，不随机抽 10 个文件。</p></button></div><div class="section"><div class="console"><div class="messages" id="messages">${chat.length?chat.map(m=>`<div class="message"><div class="role">${escapeHtml(m.role.toUpperCase())}</div><pre>${escapeHtml(m.text)}</pre></div>`).join(''):'<div class="message"><div class="role">SYSTEM</div><pre>选择任务，或直接告诉制作总监要处理什么。</pre></div>'}</div><div class="composer"><textarea id="chatInput" placeholder="告诉制作总监当前问题。"></textarea><button class="btn" id="sendChat">发送</button></div></div></div>`}</section>`;}

function renderQa(){const p=activeProject();if(!p)return'<div class="empty">先创建项目。</div>';const issues=localQa(p),s=strictScore(p),e=evidenceProfile(p);const dims=p.review?.dimensions||[];return`<section class="hero"><div><div class="eyebrow">SEPARATE REVIEWER</div><h3>完整度和质量分开。</h3><p>本地只判断“有没有足够证据进入验收”；10 分制由独立评审读取最终材料后生成，并受证据覆盖率和 P0 上限约束。</p></div><div class="hero-note"><strong>${s===null?'未评分':`${s.toFixed(2)} / 10`}</strong><span>验收准备度 ${e.coverage}% · ${p.review?`置信度 ${Math.round((p.review.confidence||0)*100)}%`:'尚未运行独立评审'}</span></div></section><section class="section"><div class="section-head"><div><h3>本地硬检查</h3></div><div class="split-actions"><button class="btn primary" id="aiQaBtn">运行证据制独立评审</button><button class="btn" id="saveQaBtn">保存本地 QA</button></div></div>${issues.length?issues.map(issueHtml).join(''):'<div class="empty">未发现规则级问题。</div>'}</section><section class="section"><div class="section-head"><div><h3>GitHub Pages 部署巡检</h3><p class="lead">真实请求页面与资源，检查 404、跨页可达性和仓库子路径；不执行浏览器 JS，因此不能替代完整点击回归。</p></div><div class="split-actions"><input id="siteAuditUrl" value="${escapeHtml(p.deployUrl||'')}" placeholder="https://mike798-cloud.github.io/repo/" style="min-width:320px;padding:8px;border:1px solid var(--line);background:var(--paper)"><button class="btn" id="siteAuditBtn">运行部署巡检</button></div></div>${p.siteAudit?`<div class="panel"><p><b>检查 ${p.siteAudit.checked||0} 个 URL，HTML ${p.siteAudit.htmlPages?.length||0} 页，失败 ${p.siteAudit.broken?.length||0} 项。</b></p>${(p.siteAudit.broken||[]).slice(0,12).map(x=>`<p class="tiny">${escapeHtml(String(x.status||0))} · ${escapeHtml(x.url||'')}</p>`).join('')||'<p class="tiny muted">未发现 HTTP 级断链。</p>'}${(p.siteAudit.outsideBase||[]).slice(0,8).map(x=>`<p class="tiny">子路径风险 · ${escapeHtml(x.ref||'')} → ${escapeHtml(x.resolved||'')}</p>`).join('')}${p.siteAudit.interaction?`<div class="interaction-strip"><span>按钮 ${p.siteAudit.interaction.buttons||0}</span><span>点击绑定 ${p.siteAudit.interaction.clickHandlers||0}</span><span>表单 ${p.siteAudit.interaction.forms||0}</span><span>状态写入 ${p.siteAudit.interaction.storageWrites||0}</span><span>根路径特征 ${p.siteAudit.interaction.absoluteRootRefs||0}</span></div>`:''}${(p.siteAudit.warnings||[]).map(x=>`<p class="tiny">静态交互提醒 · ${escapeHtml(x)}</p>`).join('')}</div>`:'<div class="empty">尚未运行部署巡检。</div>'}</section>${p.review?`<section class="section"><h3>独立评分证据</h3><div class="review-grid">${dims.map(d=>`<div class="panel"><h4>${escapeHtml(d.name)} · ${d.score==null?'—':`${Number(d.score).toFixed(1)}/10`}</h4><p><b>证据：</b>${escapeHtml(d.evidence||'无')}</p><p><b>问题：</b>${escapeHtml(d.problem||'无')}</p></div>`).join('')}</div><div class="panel audit-output">${escapeHtml(p.review.summary||'')}</div></section>`:''}`;}

function renderSettings(){return`<section class="hero"><div><div class="eyebrow">GITHUB PAGES + CLOUDFLARE WORKER</div><h3>前端公开部署，密钥留在 Worker。</h3><p>GitHub Pages 承载工作台；Worker 负责 AI、图片与 GitHub API。图片保存在浏览器 IndexedDB，普通项目 JSON 不再被 Base64 撑爆。</p></div><div class="hero-note"><strong>离线仍可工作</strong><span>项目、经验、类型初筛、本地 QA 和数据导入导出不依赖 Worker。</span></div></section><section class="section"><div class="grid-2"><div class="panel"><h4>连接设置</h4><div class="form"><div class="field"><label>Cloudflare Worker URL</label><input id="workerUrl" value="${escapeHtml(settings.workerUrl)}" placeholder="https://your-worker.workers.dev"></div><div class="field"><label>Agent Key</label><input id="appKey" type="password" value="${escapeHtml(settings.appKey)}"></div><div class="field"><label>GitHub Owner</label><input id="githubOwner" value="${escapeHtml(settings.githubOwner)}"></div><div class="split-actions"><button class="btn primary" id="saveSettingsBtn">保存并测试</button><button class="btn" id="testWorkerBtn">测试连接</button></div></div></div><div class="panel"><h4>数据</h4><p>${state.projects.length} 个项目、${state.experiences.length} 条经验。JSON 导出不包含生成图片二进制。</p><div class="split-actions"><button class="btn" id="exportSettingsData">导出 JSON</button><label class="btn" for="importFile">导入 JSON</label><input id="importFile" type="file" accept="application/json" hidden><button class="btn danger" id="resetAllBtn">恢复初始经验库</button></div></div></div></section>`;}

function bindView(){ $$('[data-go]').forEach(b=>b.onclick=()=>{currentView=b.dataset.go;render();});$$('[data-open-project]').forEach(b=>b.onclick=()=>{currentProjectId=b.dataset.openProject;currentProjectTab='bible';render();});if($('#createProjectInline'))$('#createProjectInline').onclick=()=>openProjectModal();if($('#editProjectMeta'))$('#editProjectMeta').onclick=()=>openProjectModal(activeProject());if($('#deleteProject'))$('#deleteProject').onclick=deleteActiveProject;$$('[data-project-tab]').forEach(b=>b.onclick=()=>{currentProjectTab=b.dataset.projectTab;render();});if($('#saveProjectField'))$('#saveProjectField').onclick=saveProjectEditor;$$('[data-ai-task]').forEach(b=>b.onclick=()=>runProjectTask(b.dataset.aiTask));if($('#generateImageBtn'))$('#generateImageBtn').onclick=generateImage;if($('#copyPlanBtn'))$('#copyPlanBtn').onclick=generateCopyPlan;if($('#copyAllBtn'))$('#copyAllBtn').onclick=generateAllCopySections;$$('[data-copy-section]').forEach(b=>b.onclick=()=>generateCopySection(b.dataset.copySection));if($('#genreLocalBtn'))$('#genreLocalBtn').onclick=runLocalGenre;if($('#genreAiBtn'))$('#genreAiBtn').onclick=runAiGenre;if($('#reviewExperienceBtn'))$('#reviewExperienceBtn').onclick=runExperienceReview;if($('#reviewExperienceAiBtn'))$('#reviewExperienceAiBtn').onclick=runExperienceAiReview;if($('#experienceFilter'))$('#experienceFilter').onchange=filterExperiences;$$('[data-delete-exp]').forEach(b=>b.onclick=()=>deleteExperience(b.dataset.deleteExp));if($('#loadReposBtn'))$('#loadReposBtn').onclick=()=>loadRepoList(true);if($('#scanPortfolioBtn'))$('#scanPortfolioBtn').onclick=scanPortfolio;if($('#pausePortfolioBtn'))$('#pausePortfolioBtn').onclick=()=>{portfolioStopRequested=true;toast('将在当前批次结束后暂停');};if($('#resetPortfolioScanBtn'))$('#resetPortfolioScanBtn').onclick=resetPortfolioScan;if($('#aiCatalogBtn'))$('#aiCatalogBtn').onclick=refineCatalogWithAi;if($('#resetCatalogAutoBtn'))$('#resetCatalogAutoBtn').onclick=recomputeCatalog;if($('#portfolioSearch'))$('#portfolioSearch').oninput=e=>{portfolioQuery=e.target.value;render();setTimeout(()=>$('#portfolioSearch')?.focus(),0);};if($('#portfolioCategory'))$('#portfolioCategory').onchange=e=>{portfolioCategory=e.target.value;render();};$$('[data-repo-category]').forEach(el=>el.onchange=e=>setCatalogField(el.dataset.repoCategory,'category',e.target.value));$$('[data-repo-workkey]').forEach(el=>el.onchange=e=>setCatalogField(el.dataset.repoWorkkey,'workKey',e.target.value));$$('[data-repo-auto]').forEach(el=>el.onclick=()=>unlockCatalogEntry(el.dataset.repoAuto));$$('[data-work-project]').forEach(el=>el.onclick=()=>openOrCreateWorkProject(el.dataset.workProject));$$('[data-work-analyze]').forEach(el=>el.onclick=()=>deepAnalyzeWork(el.dataset.workAnalyze));$$('[data-studio-task]').forEach(b=>b.onclick=()=>runStudioTask(b.dataset.studioTask));if($('#studioCopyPlan'))$('#studioCopyPlan').onclick=()=>{currentView='projects';currentProjectTab='copyPack';render();setTimeout(generateCopyPlan,0);};if($('#studioStrictReview'))$('#studioStrictReview').onclick=runAiQa;if($('#githubAnalyzeCard'))$('#githubAnalyzeCard').onclick=githubAnalyzePrompt;if($('#sendChat'))$('#sendChat').onclick=sendChat;if($('#aiQaBtn'))$('#aiQaBtn').onclick=runAiQa;if($('#saveQaBtn'))$('#saveQaBtn').onclick=saveLocalQa;if($('#siteAuditBtn'))$('#siteAuditBtn').onclick=runSiteAudit;if($('#saveSettingsBtn'))$('#saveSettingsBtn').onclick=saveAndTestSettings;if($('#testWorkerBtn'))$('#testWorkerBtn').onclick=testWorker;if($('#exportSettingsData'))$('#exportSettingsData').onclick=exportData;if($('#importFile'))$('#importFile').onchange=importData;if($('#resetAllBtn'))$('#resetAllBtn').onclick=resetAll;}

function saveProjectEditor(){const p=activeProject(),e=$('#projectEditor');if(!p||!e)return;p[e.dataset.field]=e.value;p.updatedAt=Date.now();save();toast('已保存');render();}
function openProjectModal(existing=null){const c=existing||{title:'',concept:'',duration:'50–70 分钟'};showModal(existing?'编辑项目':'新建网页叙事项目',`<div class="form"><div class="field"><label>作品名称</label><input id="modalTitle" value="${escapeHtml(c.title||'')}"></div><div class="field"><label>核心构想</label><textarea id="modalConcept">${escapeHtml(c.concept||'')}</textarea></div><div class="field"><label>目标时长</label><input id="modalDuration" value="${escapeHtml(c.duration||'50–70 分钟')}"></div></div>`,()=>{const title=$('#modalTitle').value.trim()||'未命名项目',concept=$('#modalConcept').value.trim(),duration=$('#modalDuration').value.trim()||'50–70 分钟',genres=recommendGenres(concept).map(x=>({id:x.id,score:x.score}));if(existing){Object.assign(existing,{title,concept,duration,genres,updatedAt:Date.now()});}else{const p=normalizeProject({id:uid('project'),title,concept,duration,genres,stage:'立项',createdAt:Date.now(),bible:'',architecture:'',puzzles:'',copyPack:'',visual:'',imagePrompt:'',qa:'',deploy:'',notes:[]});state.projects.unshift(p);currentProjectId=p.id;}save();closeModal();currentView='projects';render();});}
function showModal(title,body,onSubmit){$('#modalRoot').innerHTML=`<div class="modal-backdrop" id="modalBackdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><h3>${escapeHtml(title)}</h3><button class="icon-btn" id="modalClose">×</button></div><div class="modal-body">${body}</div><div class="modal-actions"><button class="btn" id="modalCancel">取消</button><button class="btn primary" id="modalSubmit">确认</button></div></div></div>`;$('#modalClose').onclick=closeModal;$('#modalCancel').onclick=closeModal;$('#modalSubmit').onclick=onSubmit;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal();};}
function closeModal(){$('#modalRoot').innerHTML='';}
function deleteActiveProject(){const p=activeProject();if(!p||!confirm(`确认删除「${p.title}」？`))return;state.projects=state.projects.filter(x=>x.id!==p.id);currentProjectId=state.projects[0]?.id||null;save();render();}

function portfolioContext(){return state.portfolioAudit?{repoCount:state.portfolioAudit.repoCount,summary:state.portfolioAudit.summary}:null;}
function taskPayload(p){return{project:p,experiences:relevantExperiences(p),portfolioAudit:portfolioContext()};}
function relevantExperiences(p){const ids=new Set((p.genres||[]).map(x=>x.id));return state.experiences.filter(x=>x.scope==='全局'||x.scope==='项目'||(x.genres||[]).some(g=>ids.has(g))).slice(0,60);}
async function runProjectTask(task){const p=activeProject();if(!p)return;saveProjectEditor();try{const r=await callAi(task,taskPayload(p));const map={story_bible:'bible',page_architecture:'architecture',puzzle_design:'puzzles',copy_pack:'copyPack',visual_direction:'visual',image_direction:'imagePrompt',release_plan:'deploy'};const f=map[task];if(f){p[f]=r.text;p.updatedAt=Date.now();save();render();toast('AI 结果已写入项目');}}catch(e){toast(e.message);}}

function runLocalGenre(){const c=$('#genreConcept').value,rec=recommendGenres(c),p=activeProject();$('#genreResults').innerHTML=buildGenreAdvice(rec).map(genreAdviceHtml).join('');if(p){p.concept=c;p.genres=rec.map(x=>({id:x.id,score:x.score}));p.updatedAt=Date.now();save();}toast('本地类型 DNA 已应用');}
async function runAiGenre(){const c=$('#genreConcept').value.trim(),p=activeProject();if(!c||!p)return toast('先输入构想');try{const r=await api('/api/genre/review',{concept:c,project:p});const genres=(r.result?.genres||[]).filter(x=>GENRES.some(g=>g.id===x.id)).slice(0,3);if(genres.length){p.concept=c;p.genres=genres.map(x=>({id:x.id,score:Number(x.score)||0}));p.updatedAt=Date.now();save();render();toast('AI 类型判断已结构化写回项目');}}catch(e){toast(e.message);}}

function runExperienceReview(){const text=$('#experienceInput').value.trim(),r=reviewExperience(text,state.experiences);if(!text)return toast('先写经验');$('#experienceReview').innerHTML=`<p><b>${escapeHtml(r.decision)}</b> · 价值 ${r.worth}/5 · ${escapeHtml(r.scope)}</p><p>${escapeHtml(r.reason)}</p>${r.duplicate?`<p>最相近：${escapeHtml(r.duplicate.item.title)}</p>`:''}<button class="btn small primary" id="acceptExperience">按本地建议保存</button>`;$('#acceptExperience').onclick=()=>applyExperience(text,{action:r.duplicate?'merge':'save',scope:r.scope,worth:r.worth,duplicateId:r.duplicate?.item.id||null,title:text.slice(0,30),mergedRule:text,genres:activeProject()?.genres?.map(x=>x.id)||[]});}
async function runExperienceAiReview(){const text=$('#experienceInput').value.trim();if(!text)return toast('先写经验');try{const r=await api('/api/experience/review',{text,experiences:state.experiences,project:activeProject()});const x=r.review||{};$('#experienceReview').innerHTML=`<p><b>${escapeHtml(x.action||'')}</b> · ${escapeHtml(x.scope||'')} · 价值 ${x.worth||'—'}/5</p><p>${escapeHtml(x.reason||'')}</p><p>${escapeHtml(x.mergedRule||'')}</p><button class="btn small primary" id="applyAiExperience">应用这个判断</button>`;$('#applyAiExperience').onclick=()=>applyExperience(text,x);}catch(e){toast(e.message);}}
function applyExperience(text,r){if(r.action==='reject'||r.action==='temporary'){toast(r.action==='temporary'?'仅作为本次临时判断，不写入长期经验':'未写入经验库');return;}if(r.action==='merge'&&r.duplicateId){const old=state.experiences.find(x=>x.id===r.duplicateId);if(old){old.body=r.mergedRule||`${old.body}\n${text}`;old.title=r.title||old.title;old.scope=r.scope||old.scope;old.priority=Math.max(old.priority||3,r.worth||3);save();render();toast('已合并到已有经验');return;}}state.experiences.unshift({id:uid('exp'),scope:r.scope||'项目',category:'补充经验',title:r.title||text.slice(0,30),body:r.mergedRule||text,genres:Array.isArray(r.genres)?r.genres:(activeProject()?.genres||[]).map(x=>x.id),priority:r.worth>=4?4:3,createdAt:Date.now()});save();render();toast('经验已保存');}
function filterExperiences(){const c=$('#experienceFilter').value;$('#experienceList').innerHTML=experienceListHtml(c==='全部'?state.experiences:state.experiences.filter(x=>x.category===c));bindView();}
function deleteExperience(id){if(confirm('删除这条经验？')){state.experiences=state.experiences.filter(x=>x.id!==id);save();render();}}

async function generateCopyPlan(){const p=activeProject();if(!p)return;saveProjectEditor();try{const r=await api('/api/copy/plan',taskPayload(p));const secs=(r.plan?.sections||[]).map((x,i)=>({...x,id:String(x.id||`section-${i+1}`),text:p.copySections?.find(y=>y.id===String(x.id))?.text||''}));if(!secs.length)throw new Error('文案矩阵为空');p.copyPlan=r.plan;p.copySections=secs;p.updatedAt=Date.now();save();render();toast(`已建立 ${secs.length} 个文案单元`);}catch(e){toast(e.message);}}
async function generateCopySection(id){const p=activeProject(),section=p?.copySections?.find(x=>x.id===id);if(!p||!section)return;try{const completed=p.copySections.filter(x=>x.text&&x.id!==id).map(x=>({id:x.id,title:x.title,text:x.text.slice(0,2600)}));const slim={...p,lastImage:undefined,chat:undefined,copySections:undefined};const r=await api('/api/copy/section',{project:slim,section,completed,experiences:relevantExperiences(p),portfolioAudit:portfolioContext()});section.text=r.text;rebuildCopyPack(p);save();render();toast(`已生成：${section.title}`);}catch(e){toast(e.message);}}
async function generateAllCopySections(){const p=activeProject();if(!p?.copySections?.length)return;for(const s of p.copySections.filter(x=>!x.text)){await generateCopySection(s.id);}toast('未完成文案单元已全部生成');}
function rebuildCopyPack(p){p.copyPack=p.copySections.filter(x=>x.text).map(x=>`## ${x.title}\n\n${x.text}`).join('\n\n');p.updatedAt=Date.now();}

let portfolioStopRequested=false;
function setCatalogField(repo,field,value){const x=catalogEntry(repo);if(!x)return;if(field==='category'&&!REPO_CATEGORY_LABELS[value])return;if(field==='workKey'){value=canonicalWorkKey(value)||canonicalWorkKey(repo)||repo.toLowerCase();}x[field]=value;x.manual=true;x.source='manual';x.confidence=1;x.reason='人工校正并锁定';save();render();toast('已保存人工分类，后续同步不会覆盖');}
function unlockCatalogEntry(repo){const x=catalogEntry(repo),meta=(state.repoCache||[]).find(r=>r.name===repo);if(!x||!meta)return;const next=inferRepoCatalogEntry(meta,x.signals?{signals:x.signals,entries:x.entries||[]}:null,null);Object.assign(x,next,{manual:false,source:'heuristic'});save();render();toast('已恢复自动判断');}
function recomputeCatalog(){ensureRepoCatalog();state.repoCatalog=state.repoCatalog.map(x=>{if(x.manual)return x;const meta=(state.repoCache||[]).find(r=>r.name===x.repo)||x;return inferRepoCatalogEntry(meta,x.signals?{signals:x.signals,entries:x.entries||[]}:null,null);});save();render();toast('未锁定仓库已重新执行本地分类');}
async function refineCatalogWithAi(){const items=ensureRepoCatalog().filter(x=>!x.manual);if(!items.length)return toast('没有可由 AI 校正的仓库');setBusy(true);try{for(let i=0;i<items.length;i+=18){const batch=items.slice(i,i+18),status=$('#catalogStatus');if(status)status.textContent=`AI 正在校正 ${i+1}-${Math.min(items.length,i+batch.length)}/${items.length}…`;const payload=batch.map(x=>({repo:x.repo,description:x.description,homepage:x.homepage,language:x.language,currentCategory:x.category,currentWorkKey:x.workKey,signals:x.signals?{htmlFiles:x.signals.htmlFiles,imageFiles:x.signals.imageFiles,reachableTextFiles:x.signals.reachableTextFiles,hasPayment:x.signals.hasPayment,titles:x.signals.titles,interaction:x.signals.interaction}:null,entries:(x.entries||[]).slice(0,8)}));const r=await apiRaw('/api/portfolio/catalog',{owner:settings.githubOwner,items:payload},'POST',{timeoutMs:110000});for(const j of r.items||[]){const x=catalogEntry(j.repo);if(!x||x.manual||!REPO_CATEGORY_LABELS[j.category])continue;x.category=j.category;x.workKey=canonicalWorkKey(j.workKey||x.workKey||x.repo)||canonicalWorkKey(x.repo);x.workTitle=String(j.workTitle||x.workTitle||x.repo).slice(0,120);x.confidence=Math.max(0,Math.min(1,Number(j.confidence)||.6));x.reason=String(j.reason||'AI 分类校正').slice(0,260);x.source='ai';}if(!save())throw new Error('本地存储空间不足，无法保存分类结果');}render();toast('AI 分类与作品归组校正完成');}catch(e){toast(`AI 分类未完成：${e.message}`);}finally{setBusy(false);}}
function ensureWorkProject(workKey){const group=workGroups().find(g=>g.key===workKey);if(!group)return null;if(group.linkedProject)return group.linkedProject;const main=group.main||{},concept=main.description||`从 GitHub 仓库 ${main.repo||workKey} 导入的网页作品。`;const p=normalizeProject({...clone(INITIAL_PROJECT),id:uid('project'),title:group.title||main.repo||workKey,concept,createdAt:Date.now(),updatedAt:Date.now(),stage:(main.homepage||main.has_pages)?'已发布':'GitHub 导入',genres:recommendGenres(`${group.title} ${concept}`).map(x=>({id:x.id,score:x.score})),githubWorkKey:group.key,githubRepos:{main:main.repo||'',guides:group.guides.map(x=>x.repo),old:group.old.map(x=>x.repo),tests:group.tests.map(x=>x.repo)},deployUrl:main.homepage||(main.has_pages?`https://${settings.githubOwner.toLowerCase()}.github.io/${main.repo}/`:''),portfolioAudit:state.portfolioAudit?{repoCount:state.portfolioAudit.repoCount,completedAt:state.portfolioAudit.completedAt}:null});state.projects.unshift(p);return p;}
function openOrCreateWorkProject(workKey){const p=ensureWorkProject(workKey);if(!p)return;currentProjectId=p.id;currentView='projects';currentProjectTab='bible';save();render();toast('作品工作区已打开');}
async function deepAnalyzeWork(workKey){const group=workGroups().find(g=>g.key===workKey),main=group?.main;if(!group||!main?.repo)return toast('这个归组还没有可复盘的主仓库');const p=ensureWorkProject(workKey);try{const repoUrl=main.repoUrl||`https://github.com/${settings.githubOwner}/${main.repo}`;const r=await api('/api/github/analyze',{repoUrl,project:p,experiences:relevantExperiences(p)},'POST',{timeoutMs:155000});p.githubReview={repo:main.repo,repoUrl,text:r.text,snapshot:compactScan(r.snapshot||{}),analyzedAt:Date.now()};p.chat.push({role:'assistant',text:`【GitHub 实际引用复盘｜${main.repo}】\n${r.text}`,ts:Date.now()});p.updatedAt=Date.now();updateCatalogFromScan(main.repo,r.snapshot||{});save();currentProjectId=p.id;currentView='studio';render();toast('主仓库深度复盘完成，结果已写入该项目');}catch(e){toast(`深度复盘失败：${e.message}`);}}

function compactScan(s){return{repository:s.repository,entries:(s.entries||[]).slice(0,12),referenced:(s.referenced||[]).slice(0,160),unreachableCount:s.unreachableCount,unreachableSample:(s.unreachableSample||[]).slice(0,24),filesRead:(s.filesRead||[]).slice(0,80),signals:s.signals,sample:String(s.sample||'').slice(0,7000),truncated:!!s.truncated};}
function savePortfolioCheckpoint(){if(!save())throw new Error('浏览器本地存储空间不足，扫描断点无法安全保存；请先导出项目备份或清理旧数据');}
function updatePortfolioProgress(message,phase='inspect'){const scan=state.portfolioScan;if(scan){scan.phase=phase;scan.message=message;scan.updatedAt=Date.now();savePortfolioCheckpoint();}const box=$('#portfolioProgress');if(box)box.innerHTML=portfolioProgressHtml();}
function resetPortfolioScan(){if(!confirm('清除当前扫描断点？已完成的最终作品集总结不会删除。'))return;state.portfolioScan=null;save();render();toast('扫描断点已清除');}
async function loadRepoList(force=false){try{if(!force&&state.repoCache?.length){ensureRepoCatalog();return state.repoCache;}const r=await api('/api/github/repos',{owner:settings.githubOwner});state.repoCache=r.repos||[];state.repoCatalog=mergeRepoCatalog(state.repoCache,state.repoCatalog||[]);if(force&&state.portfolioScan&&!state.portfolioScan.finished){const current=state.portfolioScan.repoNames||[],fresh=state.repoCache.filter(x=>!x.archived&&!x.fork).map(x=>x.name);if(current.join('\n')!==fresh.join('\n'))state.portfolioScan=null;}save();render();toast(`读取到 ${state.repoCache.length} 个公开仓库，已同步作品整理表`);return state.repoCache;}catch(e){toast(e.message);return[];}}
async function inspectOneRepo(repo){try{return{name:repo.name,scan:compactScan(await apiRaw('/api/github/inspect',{owner:settings.githubOwner,repo:repo.name},'POST',{timeoutMs:45000}))};}catch(err){return{name:repo.name,error:err.message};}}
async function mapLimit(items,limit,fn){const out=new Array(items.length);let cursor=0;async function runner(){while(cursor<items.length){const i=cursor++;out[i]=await fn(items[i],i);}}await Promise.all(Array.from({length:Math.min(limit,items.length)},runner));return out;}
function fallbackBatchReview(results){const lines=results.map(x=>{if(x.error)return`${x.name}：扫描失败（${x.error}）`;const g=x.scan?.signals||{};return`${x.name}：可达文本 ${g.reachableTextFiles||0}，引用文件 ${g.referencedFiles||0}/${g.totalRepoFiles||0}，HTML ${g.htmlFiles||0}，CSS ${g.cssFiles||0}，图片 ${g.imageFiles||0}${g.hasLockedLanguage?'；存在章节/未解锁措辞':''}${g.hasAiCliche?'；命中高频AI恐怖套话':''}`;});return`【本批自动降级摘要｜AI 批次总结失败】\n${lines.join('\n')}\n后续总结合并时必须降低对此批次的置信度。`;}
async function retryOnce(fn,onRetry){try{return await fn();}catch(e){onRetry?.(e);await new Promise(r=>setTimeout(r,1200));return fn();}}
async function scanPortfolio(){let repos=state.repoCache?.length?state.repoCache:await loadRepoList();ensureRepoCatalog();repos=repos.filter(r=>!r.archived&&!r.fork&&catalogEntry(r.name)?.category!=='tool');if(!repos.length)return;portfolioStopRequested=false;const names=repos.map(r=>r.name);let scan=normalizePortfolioScan(state.portfolioScan);const compatible=scan&&scan.owner===settings.githubOwner&&JSON.stringify(scan.repoNames)===JSON.stringify(names)&&!scan.finished;if(!compatible){scan=normalizePortfolioScan({owner:settings.githubOwner,repoNames:names,batches:[],pending:[],errors:[],phase:'inspect',startedAt:Date.now(),updatedAt:Date.now(),finished:false,message:'准备开始'});state.portfolioScan=scan;savePortfolioCheckpoint();}
  try{
    while(true){const processed=portfolioProcessed(scan),remaining=repos.filter(r=>!processed.has(r.name));if(!remaining.length&&!(scan.pending||[]).length)break;
      const pending=scan.pending||[];const need=Math.max(0,6-pending.length);const todo=remaining.slice(0,need);if(todo.length){const baseDone=processed.size;updatePortfolioProgress(`${baseDone+1}-${Math.min(repos.length,baseDone+todo.length)}/${repos.length} 正在并行检查：${todo.map(x=>x.name).join('、')}`,'inspect');const results=await mapLimit(todo,Math.min(3,todo.length),r=>inspectOneRepo(r));for(const result of results){pending.push(result);if(result.scan)updateCatalogFromScan(result.name,result.scan);if(result.error)scan.errors.push({repo:result.name,error:result.error,at:Date.now()});scan.pending=pending;scan.updatedAt=Date.now();savePortfolioCheckpoint();}}
      if(portfolioStopRequested){scan.phase='paused';scan.message=`已保存 ${portfolioProcessed(scan).size}/${repos.length} 的断点`;scan.updatedAt=Date.now();savePortfolioCheckpoint();render();toast('已暂停，可稍后继续');return;}
      if(!pending.length)break;
      const batchNames=pending.map(x=>x.name);updatePortfolioProgress(`✓ ${batchNames.join('、')} 引用链检查完成。正在总结第 ${scan.batches.length+1} 批（${batchNames.length} 个仓库）…`,'review');let text;try{const review=await retryOnce(()=>callAiRaw('portfolio_batch_review',{owner:settings.githubOwner,repositories:pending.map(x=>x.error?{repository:{repo:x.name},catalogRole:catalogEntry(x.name)?.category||'unknown',error:x.error}:{...x.scan,catalogRole:catalogEntry(x.name)?.category||'unknown'}),portfolioAuditVersion:3},{timeoutMs:120000}),()=>updatePortfolioProgress(`AI 批次总结首次未完成，正在重试一次…`,'review'));text=review.text;}catch(e){text=fallbackBatchReview(pending);scan.errors.push({repo:`批次 ${scan.batches.length+1}`,error:`AI总结失败：${e.message}`,at:Date.now()});}
      scan.batches.push({repos:batchNames,text,at:Date.now(),fallback:text.startsWith('【本批自动降级摘要')});scan.pending=[];scan.updatedAt=Date.now();scan.message=`第 ${scan.batches.length} 批已保存`;savePortfolioCheckpoint();if(portfolioStopRequested){scan.phase='paused';savePortfolioCheckpoint();render();toast('已暂停，可稍后继续');return;}
    }
    updatePortfolioProgress(`全部 ${repos.length} 个仓库已处理，正在合并跨作品方法论…`,'synthesis');let final;try{final=await retryOnce(()=>callAiRaw('portfolio_synthesis',{owner:settings.githubOwner,repoCount:repos.length,batchReviews:scan.batches.map(x=>x.text),scanErrors:scan.errors,portfolioAuditVersion:3},{timeoutMs:150000}),()=>updatePortfolioProgress('总结合并首次未完成，正在重试一次…','synthesis'));}catch(e){scan.phase='error';scan.message=`仓库扫描已完成，但最终总结失败：${e.message}`;scan.updatedAt=Date.now();savePortfolioCheckpoint();render();toast('扫描结果已保存；稍后点“继续扫描”只会重试最终总结');return;}
    state.portfolioAudit={owner:settings.githubOwner,repoCount:repos.length,successCount:repos.length-new Set((scan.errors||[]).filter(x=>names.includes(x.repo)).map(x=>x.repo)).size,failedCount:new Set((scan.errors||[]).filter(x=>names.includes(x.repo)).map(x=>x.repo)).size,completedAt:Date.now(),batchCount:scan.batches.length,summary:final.text};for(const p of state.projects)p.portfolioAudit={repoCount:repos.length,completedAt:Date.now()};scan.phase='done';scan.finished=true;scan.message=`全量复盘完成，共 ${scan.batches.length} 批`;scan.updatedAt=Date.now();savePortfolioCheckpoint();render();toast('作品集全量复盘完成，已成为全局制作上下文');
  }catch(e){scan.phase='error';scan.message=e.message;scan.updatedAt=Date.now();savePortfolioCheckpoint();render();toast(`扫描已保存断点：${e.message}`);}}

async function runStudioTask(task){const p=activeProject();if(!p)return;try{const r=await callAi(task,taskPayload(p));p.chat.push({role:'assistant',text:r.text,ts:Date.now()});save();render();}catch(e){toast(e.message);}}
async function sendChat(){const p=activeProject(),input=$('#chatInput'),text=input?.value.trim();if(!p||!text)return;p.chat.push({role:'user',text,ts:Date.now()});save();render();try{const r=await callAi('director_chat',{message:text,...taskPayload(p),history:p.chat.slice(-10)});p.chat.push({role:'assistant',text:r.text,ts:Date.now()});save();render();}catch(e){toast(e.message);}}
function githubAnalyzePrompt(){showModal('复盘 GitHub 公开仓库',`<div class="field"><label>仓库地址</label><input id="repoUrl" placeholder="https://github.com/${escapeHtml(settings.githubOwner)}/xu-yuan"></div><p class="tiny muted">从入口文件追踪实际引用依赖；未引用文件只作为疑似残留提示。</p>`,()=>{const url=$('#repoUrl').value.trim();if(!url)return;closeModal();githubAnalyze(url);});}
async function githubAnalyze(url){const p=activeProject();try{const r=await api('/api/github/analyze',{repoUrl:url,project:p,experiences:relevantExperiences(p||{genres:[]})},'POST',{timeoutMs:150000});if(p){p.chat.push({role:'assistant',text:r.text,ts:Date.now()});save();currentView='studio';render();}}catch(e){toast(e.message);}}

async function runAiQa(){const p=activeProject();if(!p)return;saveProjectEditor();try{const r=await api('/api/review',{project:p,experiences:relevantExperiences(p),portfolioAudit:portfolioContext()});p.review={...r.review,reviewedAt:Date.now()};save();render();toast(r.review?.score==null?'材料不足，评审没有强行给分':`独立评分 ${Number(r.review.score).toFixed(2)}/10`);}catch(e){toast(e.message);}}
function saveLocalQa(){const p=activeProject();p.qa=`本地硬检查｜${new Date().toLocaleString()}\n\n`+localQa(p).map(i=>`${i.severity} ${i.title}\n${i.detail}`).join('\n\n');p.updatedAt=Date.now();save();render();toast('本地 QA 已保存；这不是质量评分');}
async function runSiteAudit(){const p=activeProject(),url=$('#siteAuditUrl')?.value.trim();if(!p||!url)return toast('先填写 GitHub Pages 部署地址');try{const r=await api('/api/site/audit',{url});p.deployUrl=url;p.siteAudit=r;p.updatedAt=Date.now();save();render();toast(r.broken?.length?`部署巡检发现 ${r.broken.length} 个 HTTP 问题`:'部署巡检未发现 HTTP 断链');}catch(e){toast(e.message);}}

function workerBase(){return settings.workerUrl.replace(/\/$/,'');}
async function apiRaw(path,body=null,method='POST',options={}){if(!workerBase())throw new Error('还没有配置 Cloudflare Worker URL');const headers={'content-type':'application/json'};if(settings.appKey)headers['x-agent-key']=settings.appKey;const timeoutMs=Number(options.timeoutMs||90000),controller=new AbortController(),timer=setTimeout(()=>controller.abort(),timeoutMs);let res;try{res=await fetch(workerBase()+path,{method,headers,body:body?JSON.stringify(body):undefined,signal:controller.signal});}catch(e){if(e?.name==='AbortError')throw new Error(`请求超过 ${Math.round(timeoutMs/1000)} 秒，已自动中止`);throw e;}finally{clearTimeout(timer);}const text=await res.text();let data;try{data=JSON.parse(text);}catch{data={error:text};}if(!res.ok)throw new Error(data.error||`Worker 返回 ${res.status}`);return data;}
async function api(path,body=null,method='POST',options={}){setBusy(true);try{return await apiRaw(path,body,method,options);}finally{setBusy(false);}}
async function callAiRaw(task,payload,options={}){return apiRaw('/api/ai',{task,payload},'POST',options);}
async function callAi(task,payload,options={}){return api('/api/ai',{task,payload},'POST',options);}
async function testWorker(){try{if(!workerBase())throw new Error('请先填写 Worker URL');setBusy(true);const headers={};if(settings.appKey)headers['x-agent-key']=settings.appKey;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),15000);let r;try{r=await fetch(workerBase()+'/api/ping',{headers,signal:controller.signal});}finally{clearTimeout(timer);}let j={};try{j=await r.json();}catch{}if(r.status===401)throw new Error('Agent Key 与 Cloudflare 的 APP_SECRET 不一致');if(!r.ok)throw new Error(j.error||'连接失败');if(!j.ai)throw new Error('Worker 已连接，但 Workers AI binding 不可用');$('#workerDot').classList.add('live');$('#workerLabel').textContent=`AI 已连接 · ${j.model}`;toast(j.github?'Worker、AI、GitHub 身份均正常':'Worker 与 AI 正常，但尚未检测到 GITHUB_TOKEN');}catch(e){$('#workerDot').classList.remove('live');$('#workerLabel').textContent='AI 未连接';toast(e?.name==='AbortError'?'Worker 连接测试超时':e.message);}finally{setBusy(false);}}
async function saveAndTestSettings(){settings.workerUrl=$('#workerUrl').value.trim();settings.appKey=$('#appKey').value.trim();settings.githubOwner=$('#githubOwner').value.trim()||'Mike798-cloud';saveSettings();await testWorker();}

async function openImageDb(){return new Promise((resolve,reject)=>{const q=indexedDB.open('narrative-agent-assets',1);q.onupgradeneeded=()=>q.result.createObjectStore('images');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(q.error);});}
async function storeImage(projectId,dataURI){const db=await openImageDb();return new Promise((resolve,reject)=>{const tx=db.transaction('images','readwrite');tx.objectStore('images').put(dataURI,projectId);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function getImage(projectId){const db=await openImageDb();return new Promise((resolve,reject)=>{const q=db.transaction('images').objectStore('images').get(projectId);q.onsuccess=()=>resolve(q.result||'');q.onerror=()=>reject(q.error);});}
async function generateImage(){const p=activeProject(),prompt=$('#projectEditor')?.value.trim()||p?.imagePrompt;if(!p||!prompt)return toast('先完成图片设计说明');try{const r=await api('/api/image',{prompt,project:{title:p.title,concept:p.concept,genres:p.genres}});p.lastImage=r.dataURI;p.imageGeneratedAt=Date.now();p.updatedAt=Date.now();save();await storeImage(p.id,r.dataURI);$('#imageArea').innerHTML=`<img class="image-preview" src="${r.dataURI}" alt="生成图片预览">`;toast('图片已保存到浏览器资产库，刷新后仍可恢复');}catch(e){toast(e.message);}}
async function hydrateVisibleImage(){const p=activeProject(),area=$('#imageArea');if(!p||!area||p.lastImage)return;try{const img=await getImage(p.id);if(img){p.lastImage=img;area.innerHTML=`<img class="image-preview" src="${img}" alt="生成图片预览">`;}}catch{}}

function exportData(){const blob=new Blob([JSON.stringify({state:serializableState(),settings:{...settings,appKey:''},exportedAt:new Date().toISOString()},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`narrative-agent-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);}
async function importData(ev){const f=ev.target.files?.[0];if(!f)return;try{const obj=JSON.parse(await f.text());if(!obj.state?.projects||!obj.state?.experiences)throw new Error('不是有效备份');state=obj.state;state.projects.forEach(normalizeProject);const known=new Set(state.experiences.map(x=>x.id));for(const seed of EXPERIENCE_SEED)if(!known.has(seed.id))state.experiences.push(clone(seed));state.portfolioAudit=state.portfolioAudit||null;state.portfolioScan=normalizePortfolioScan(state.portfolioScan);state.repoCache=state.repoCache||[];state.repoCatalog=mergeRepoCatalog(state.repoCache,state.repoCatalog||[]);currentProjectId=state.projects[0]?.id||null;save();render();toast('数据已导入');}catch(e){toast(e.message);}}
function resetAll(){if(!confirm('恢复初始经验库并重置所有项目？'))return;localStorage.removeItem(STORAGE_KEY);localStorage.removeItem('narrative_agent_state_v1');state=loadState();currentProjectId=state.projects[0]?.id;render();}

$('#nav').addEventListener('click',e=>{const b=e.target.closest('button[data-view]');if(!b)return;currentView=b.dataset.view;render();});
$('#newProjectBtn').onclick=()=>openProjectModal();$('#exportBtn').onclick=exportData;render();if(workerBase())testWorker();
